import React from "react";
import Navbar from "../../1.Navbar.js";

import '../../../App.css';

import { Col, Row } from "react-bootstrap";




import fiume from "../../../img/Italia/Trezzo/fiume.jpg";
import cielo from "../../../img/Italia/Trezzo/cielo.jpg";
import oca from "../../../img/Italia/Trezzo/oca.jpg";
import panorama from "../../../img/Italia/Trezzo/panorama.jpg";
import luna from "../../../img/Italia/Trezzo/luna.jpg";
import biblio1 from "../../../img/Italia/Trezzo/biblio1.jpg";
import nuvolo from "../../../img/Italia/Trezzo/nuvolo.jpg";
import cielotrezzo from "../../../img/Italia/Trezzo/cielotrezzo.jpg";
import finestrabiblio from "../../../img/Italia/Trezzo/finestrabiblio.jpg";
import fiori from "../../../img/Italia/Trezzo/fiori.jpg";





const Trezzo = () => {

    return(
<div>
        <Navbar/>

        <Row>

        <Col   className="bordoColonna" md={2} >
          <div className='sticky-top'>
        
         <h1 className='vertical-rl sticky-top '>Trezzo Sull'adda</h1>
         
          </div>
        
          
        </Col>
        <Col>

        <div className="maint-container">
        <div className="gridt-container">
          <div className="cardt cardt--2x">
            <div className="cardt__image">
              <img src={cielo} alt=""/>
            </div>
          </div>

          <div className="cardt cardt--2x">
            <div className="cardt__image">
              <img src={oca} alt=""/>
            </div>
          </div>
            
       
         
          <div className="cardt cardt--featured">
            <div className="cardt__side-by-side--m">
              <div className="cardt__image">
                <img src={fiume} alt=""/>
              </div>
              <div className="cardt__content paddingt-large--l">
                <h2>Trezzo Sull'adda</h2>
                <p>Raccoglierò in questa scheda le migliori foto scattate di Trezzo sull'Adda, la citta dove sono cresciuto 🙂
                </p>
              </div>
            </div>
          </div>
        
          <div className="cardt cardt--2x">
            <div className="cardt__image">
              <img src={panorama} alt=""/>
            </div>
          </div>


          <div className="cardt cardt--2x">
            <div className="cardt__image">
              <img src={luna} alt=""/>
            </div>
          </div>

            <div className="cardt cardt--2x">
            <div className="cardt__image">
              <img src={biblio1} alt=""/>
            </div>
          </div>

            <div className="cardt cardt--2x">
            <div className="cardt__image">
              <img src={finestrabiblio} alt=""/>
            </div>
          </div>

            <div className="cardt cardt--2x">
            <div className="cardt__image">
              <img src={nuvolo} alt=""/>
            </div>
          </div>

            <div className="cardt cardt--vertical">
            <div className="cardt__image">
              <img src={cielotrezzo} alt=""/>
            </div>
          </div>

          
            <div className="cardt cardt--vertical">
            <div className="cardt__image">
              <img src={fiori} alt=""/>
            </div>
          </div>
        
         
          
          
        </div>
      </div>

      </Col>

      </Row>

   

      </div>

      
    );
}

export default Trezzo;